    feeTierSubtitle: '배지 기반 수수료 감면',
    feeTierDesc: '당사의 혁신적인 수수료 구조는 플랫폼 수수료를 크게 줄여 DeHub 토큰 보유자에게 보상을 제공합니다. 표준 수수료 10% 에서 시작하여 토큰 보류 증가를 통해 획득한 각 배지 등급은 수수료를 0.69% 줄여 궁극적으로 메갈로돈 배지 소지자의 경우 1% 에 불과합니다. 이는 가장 헌신적인 커뮤니티 회원의 경우 99% 의 수수료 절감입니다.',
