    contactItem1: '커뮤니티 포럼 방문',
    contactItem2: '거버넌스 토론 참여',
    contactItem3: 'DAO를 통한 제안 제출',
    contactNote: '이 개인정보 보호정책은 커뮤니티 거버넌스 프로세스를 통해 업데이트될 수 있습니다. 중요한 변경 사항은 공식 채널을 통해 전달됩니다.',
    importantNotice: '중요 공지',
    importantNoticeText: 'DeHub은 탈중앙화 프로토콜로 운영됩니다. 사용자 프라이버시 보호를 위해 노력하지만, 탈중앙화 특성으로 인해 상호작용이 공개 블록체인에서 표시될 수 있습니다.',
    lastUpdatedDate: '2026년 9월 29일',
    doCollectItem1: '로그인 한 식별자 — 해당 경로 중 하나를 선택한 경우 이메일 주소 또는 전화 번호, 사회적으로 로그인 한 경우 Google, Apple 또는 Telegram이 반환하는 ID 또는 암호의 공개 자격 증명. 지갑 로그인은 공개 주소만 제공합니다.',
    doCollectItem7: '켜기로 선택한 항목: 문자 알림을 위한 전화번호, 온라인 상태일 때 다른 사람이 볼 수 있는지 여부, 다중 게시를 위해 연결한 외부 소셜 계정.',
    doCollectItem8: '어떤 페이지가 방문되고 어떻게 사람들이 그들 사이를 이동하는지, 그래서 우리는 무엇이 작동하는지 볼 수 있습니다. 제휴사 페이지를 직접 방문한 횟수는 계산되지 않습니다.',
    dontCollectItem6: '당신의 카드 정보는 물론, 끝에서 끝으로 암호화된 직접 메시지의 텍스트도 읽을 수 없습니다. 메시지에 첨부된 사진, 비디오, 파일, 그리고 암호화 해제하지 않은 상대방에게 보낸 메시지는 아직 끝에서 끝으로 암호화되지 않았습니다.',
    thirdPartyItem6: 'DeHub의 자체 인제스트는 Livepeer를 대체로 라이브 비디오를 전달하고 Agora는 라이브 오디오 룸을 전달합니다.',
    thirdPartyItem8: '세대, 번역, 캡션 또는 더빙 기능으로 전송하는 텍스트 및 미디어는 해당 요청에 대해서만 해당 기능을 실행하는 공급자에게 전달됩니다. 메시지, 답장, 어시스턴트 채팅과 같은 비공개 텍스트는 무료 등급을 받은 업체에 전송되지 않습니다.',
    thirdPartyItem9Prefix: '암호화폐로 구매 및 결제:',
    thirdPartyItem9: '문화페이(MoonPay)는 카드로 ETH와 USDC를 판매하며, NEAR Intents, deBridge 및 분산형 거래소는 당신이 지불한 암호화폐를 변환합니다. 각 플랫폼은 처리하는 결제를 자체적으로 확인합니다.',
    thirdPartyItem10Prefix: '다중 게시:',
    thirdPartyItem10: '다른 소셜 계정을 연결하면 보내기로 선택한 게시물이 게시 서비스를 통해 해당 플랫폼에 전달되고 승인한 서명자를 통해 Farcaster에 전달됩니다.',
    dataSovereigntyItem5: '당신의 작품이 AI 시스템의 학습에 사용될 수 있는지를 선택할 수 있습니다. 설정에서 꺼놓지 않는 한 허용되며, 우리 사이트가 통제하는 페이지의 크롤러들에게 선택 사항이 공개됩니다.',
    dataSovereigntyItem6: '설정에서 직접 계정을 삭제할 수 있습니다. 백업 사본을 포함한 프로필, 업로드 및 저장된 미디어가 지워집니다.',
    whatWeDoCollect: '수집 항목:',
    doCollectItem2: '계정: 사용자 이름, 프로필 세부 정보, 아바타, 팔로우하는 사람 및 선택한 설정. 여러 개의 프로필이 하나의 장치에 놓일 수 있으며 각각은 동일한 방식으로 저장됩니다.',
    doCollectItem3: '게시하는 내용 — 게시물, 댓글, 업로드 및 주변 메타데이터 — 이를 게시한 사람에게 제공할 수 있습니다.',
    doCollectItem4: '제품이 실행해야 하는 사항: 게시물을 보고 참여도를 계산하며, 활성 세션을 보고 취소할 수 있도록 세션 속성을 유지하는 장치 식별자.',
    doCollectItem5: 'Stripe를 통해 결제하든 온체인으로 결제하든 구매한 모든 것에 대한 결제 기록은 회계 및 분쟁에 대해 보관됩니다. 카드 번호는 Stripe에서 처리하며 당사에 절대 연락하지 않습니다.',
    doCollectItem6: '무언가가 고장 났을 때 진단하므로 고칠 수 있습니다.',
