    step1Desc: 'Dehub.io를 열고 로그인 을 누릅니다. Google, Apple, Telegram, 이메일, SMS, 비밀번호 또는 지갑을 선택하세요. 백그라운드에서 비수탁 지갑이 생성되고 (열쇠를 쥐고 있음) 가스가 후원되므로 시작하기 전에 자금을 조달할 것이 없습니다.',
    step2Title: '프로필 설정하기',
    step2Desc: '설정 → 프로필에 표시 이름, 사용자 이름, 아바타, 커버 이미지 및 약력을 추가하고 다른 소셜을 연결하여 프로필에 총 도달 횟수가 표시되도록 합니다. 방문하는 동안 → 설정 모양에서 테마를 선택하고, 원하는 경우 선택적으로 가이드 안내를 받으세요.',
    step3Title: '첫 포스트 작성하기',
    step3Desc: '작성 을 누릅니다. 포스트를 작성하거나, 이미지, 동영상 또는 오디오를 추가하거나, 장문의 글을 작성하려면 게시글 로 전환하거나, 게시글을 게시하세요. 게시물은 일일 허용량까지 무료입니다. 배지 없이 하루에 10개의 텍스트 게시물과 1기가바이트의 미디어를 게시할 수 있습니다. 온체인에서 포스트를 주조하는 것은 선택 사항이며 나중에 할 수 있습니다.',
    step4Title: '잠재고객을 통한 수익 창출',
    step4Desc: '모든 게시물은 DeHub 토큰으로 팁을 줄 수 있습니다. 여기에서 구독을 판매하고, 유료 포스트를 게시하고, 다이렉트 메시지에 대한 최소 팁을 설정하고, 스토어를 열고, 현상금을 게시하고, 제휴 링크를 공유하여 가져온 사람들로부터 수익을 올릴 수 있습니다.',
    step5Title: '토큰을 보류하고 배지를 받으세요',
    step5Desc: 'DeHub 토큰을 보유하거나 스테이킹하면 게에서 메갈로돈에 이르기까지 배지를 받게 됩니다. 배지는 수수료를 낮추고, 게시 허용 한도를 높이며, 슈퍼파워를 잠금 해제하고, 조회수, 반응 및 투표에 비중을 더합니다.',
    step6Title: '지갑을 사용하세요',
