    title: '개요',
    subtitle: 'DeHub를 지원하는 통화',
    intro: 'DeHub 토큰은 DeHub 네트워크의 기본 유틸리티 통화이며 DHB는 티커 기호입니다. 그들은 모든 d \'app에서 단일 계정 단위입니다. 팁을 주고, 콘텐츠를 잠금 해제하고, 보고, 만들고, AI 생성에 지출하는 것입니다. 그들은 체인에 살고 있기 때문에 생태계에서 가치 있는 모든 움직임은 개인 원장에 앉아 있지 않고 공개적으로 확인할 수 있습니다.',
    howItWorksTitle: '앱 내 통화 이용 방법',
    howItWorksDesc1: '모든 DeHub 계정에는 지갑이 내장되어 있습니다. Stripe 게이트웨이를 통해 카드로 자금을 조달하거나, 다른 사용자로부터 받거나, 플랫폼에서 적립하거나, 자체 보호 지갑에서 입금할 수 있습니다. 시작에 별도의 앱, 확장 프로그램 또는 시드 문구가 필요하지 않습니다. 잔액, 팁, 잠금 해제 및 보상은 모두 DeHub 토큰에 정산되므로, 자르고 계정을 동결할 수 있는 결제 프로세서를 통해 라우팅되는 대신 값이 사용자 간에 직접 이동합니다.',
    howItWorksDesc2: '보류하고 스테이킹하면 앱의 작동 방식도 변경됩니다. DeHub 토큰을 더 많이 보유할수록 플랫폼 수수료가 낮아지고 배지, 인증, 트렌드 부스트, 클럽 등급 및 네트워크 전반에 걸친 향상된 권한 등 더 많은 기능을 이용할 수 있습니다. 실제로 통화는 볼트온이 아닙니다. 권한 계층, 보상 레일 및 체크아웃을 동시에 수행합니다.',
