    profitShareDesc2: '분배는 프로토콜이 실제로 벌어들이는 수익에서 다양한 간격으로 자금이 조달되며 스테이킹된 금액과 기간에 따라 스테이킹된 계층 간에 분할됩니다. 약속이 길어지면 각 배포에서 더 많은 몫을 얻습니다. 등급 메커니즘 및 정확한 리워드 계산은 스테이크 를 참조하세요.',
    pegTitle: '말뚝 박힌 가격과 DEX 숙소',
    pegDesc1: 'DeHub 토큰은 유틸리티 토큰입니다. 인앱 목적의 경우 현재 토큰당 $ 0.001로 고정되어 있으며, 이는 명목화폐 게이트웨이를 통해 구매할 때 표시되는 요율과 인앱 가격 책정에 사용되는 요율입니다. 이 PEG는 네트워크가 확장되는 동안 앱 내 경제를 안정적이고 예측 가능한 상태로 유지하기 위해 존재합니다. 이는 미래 가치에 대한 바닥, 보장 또는 약속이 아닌 내부 회계 비율입니다.',
    pegDesc2: '토큰은 분산된 거래소에서 거래되며, 유동성 풀은 여러 체인에서 동일한 0.001 기본 가격에서 시딩됩니다. 오픈 마켓에서 가격은 DeHub가 아닌 거래에 의해 설정됩니다. 즉, DeHub 토큰은 언제든지 인앱 페그 위 또는 아래에서 거래할 수 있습니다. DeHub는 모든 거래가 체인에서 공개적으로 검증 가능한 상태로 유지되도록 DEX에 공식 유동성을 제공합니다.',
    disclaimer: '면책 조항',
    disclaimerNoApy: '중요: DeHub 토큰을 보유하면 DeHub 네트워크에서 소유권이 부여되고 스테이커가 프로토콜 이익의 일부를 얻을 수 있지만, 정해진 APY, 보장된 수익률 및 어떤 종류의 이익도 기대할 수 없습니다. 모든 배포는 네트워크 성능과 프로토콜이 특정 기간에 실제로 창출하는 수익에 전적으로 의존합니다. 보상은 이전 기간보다 낮을 수 있으며 0일 수 있습니다. 이 페이지의 어떤 내용도 수익의 약속, 예측 또는 제안이 아니며, 여기의 어떤 내용도 재정적 조언이 아닙니다.',
    disclaimerText: 'DeHub 토큰은 게임 내 또는 앱 내 디지털 토큰 또는 통화와 동일한 방식으로 유틸리티 목적을 위해 엄격히 사용되며 엄격하게 투자가 아닙니다. 토큰이 온체인에 존재하기 때문에 전례 없는 수준의 검증 가능한 투명성뿐만 아니라 추가된 유용성을 제공할 수 있습니다. 위의 데이터는 투명성, 교육 및 정보 제공 목적으로만 수집됩니다. DeHub 및 모든 계열사는 당사가 배포하는 토큰 또는 NFT를 구매함으로써 발생하는 재정적 손실에 대해 책임을 지지 않습니다. 시장은 매우 변동성이 큽니다. 또한 역량 실패, 기술적 오류, 해킹 등과 같은 예기치 않은 오류로 인해 모든 비용을 잃을 수 있습니다. 따라서 잃을 여유가 있는 것만 사용해야 합니다.',
